-- Subscription enhancements for tier tracking and rollover\n\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_status VARCHAR(20);\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_current_period_start TIMESTAMP WITH TIME ZONE;\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_current_period_end TIMESTAMP WITH TIME ZONE;\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_next_renewal_at TIMESTAMP WITH TIME ZONE;\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_last_credit_issued_at TIMESTAMP WITH TIME ZONE;\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_report_discount INTEGER DEFAULT 0;\nALTER TABLE users ADD COLUMN IF NOT EXISTS subscription_priority BOOLEAN DEFAULT FALSE;\n\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS tier VARCHAR(50);\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS current_period_start TIMESTAMP WITH TIME ZONE;\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS current_period_end TIMESTAMP WITH TIME ZONE;\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS rollover_days INTEGER;\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS report_discount INTEGER;\nALTER TABLE subscriptions ADD COLUMN IF NOT EXISTS priority_access BOOLEAN DEFAULT FALSE;\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_subscriptions_user_id ON subscriptions(user_id);
